export const documentExportButtons=(prefix)=>`<button type="button" class="btn secondary" id="${prefix}-docx" data-document-export="docx">导出 DOCX</button><button type="button" class="btn secondary" id="${prefix}-pdf" data-document-export="pdf">导出 PDF</button>`;
let fontPromise;
async function font(){if(!fontPromise)fontPromise=fetch('/workspace/assets/fonts/NotoSansSC-Regular.otf').then(r=>{if(!r.ok)throw Error('中文字体加载失败，请稍后重试。');return r.arrayBuffer();}).catch(e=>{fontPromise=null;throw e;});return fontPromise;}
export function bindDocumentExports(prefix,getText,getTitle,status){for(const format of ['docx','pdf']){const b=document.getElementById(prefix+'-'+format);if(!b)continue;b.addEventListener('click',async()=>{const text=getText();if(!text.trim()){status.textContent='请先填写或生成需要导出的内容。';return;}const buttons=['docx','pdf'].map(f=>document.getElementById(prefix+'-'+f)),before=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);status.textContent=format==='pdf'?'正在生成 PDF，首次需要加载本地中文字体…':'正在生成 Word 文档…';try{const api=await import('./assets/writing-document.js'),bytes=format==='pdf'?await api.createWritingPdf(text,await font()):await api.createWritingDocx(text),url=URL.createObjectURL(new Blob([bytes],{type:format==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})),a=document.createElement('a');a.href=url;a.download=(getTitle()||'研究成果').replace(/[\\/:*?"<>|]/g,'_')+'.'+format;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);status.textContent=`已发起 ${format.toUpperCase()} 下载；请核对分页和最终格式。`;}catch(e){status.textContent=e.message||'导出失败，请重试或使用 TXT 备份。';}finally{buttons.forEach((b,i)=>b.disabled=before[i]);}});}}
